class gsl_sf_result(ctypes.Structure):
    _fields_ = [('val', ctypes.c_double), ('err', ctypes.c_double)]

def transport_2(x):
    try:
        lib_path_cblas = "/usr/local/gsl/lib/libgslcblas.so"
        lib_path_gsl = "/usr/local/gsl/lib/libgsl.so"

        if not os.path.exists(lib_path_cblas) or not os.path.exists(lib_path_gsl):
            raise FileNotFoundError("GSL libraries not found at the specified paths.")

        ctypes.CDLL(lib_path_cblas, mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL(lib_path_gsl)

        result = gsl_sf_result()
        x_c = ctypes.c_double(x)
        gsl.gsl_sf_transport_2.argtypes = [ctypes.c_double, ctypes.POINTER(gsl_sf_result)]
        gsl.gsl_sf_transport_2.restype = ctypes.c_int

        status = gsl.gsl_sf_transport_2(x_c, ctypes.byref(result))

        if status != 0:
            raise RuntimeError(f"GSL function returned error code {status}")

        return float(result.val)
    except Exception as e:
        print(f"Error: {e}")
        return None

