    matrix = GSLMatrix()
    matrix_data = (ctypes.c_double * (np_array.shape[0] * np_array.shape[1]))()
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            matrix_data[i * np_array.shape[1] + j] = np_array[i, j]
    gsl_matrix_memcpy = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_memcpy
    gsl_matrix_memcpy.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.POINTER(GSLMatrix)]
    gsl_matrix_memcpy.restype = ctypes.c_int
    return matrix

