import ctypes
import numpy as np

class GSLFunction(ctypes.Structure):
    _fields_ = [('f', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p)))]


def wrapper(x, params):
    func = params.contents.f
    return func(x, params)

def test_func(x):
    return 1.0 / (x - 1.0)


def integrate_with_singularity(func, a, b, c):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.qc25c.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int)]
    gsl.qc25c.restype = None

    params = ctypes.pointer(ctypes.pointer(GSLFunction(f=ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p)(lambda x, params: func(x)))))

    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    relerr = ctypes.c_int(0)

    gsl.qc25c(params, a, b, c, 1000, 1000, 1000, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(relerr))

    return (result.value, abserr.value, relerr.value)

