def compute_covariance(jacobian, epsrel):
    if not isinstance(jacobian, np.ndarray) or len(jacobian.shape) != 2:
        raise ValueError("Jacobian must be a 2D numpy array.")
    if jacobian.ndim != 2:
        raise ValueError("Jacobian must be a 2D numpy array.")
    if jacobian.size == 0:
        raise ValueError("Jacobian cannot be empty.")
    if epsrel <= 0.0:
