import ctypes
import sys

class GSLMatrix:
    def __init__(self, rows, cols):
        self._matrix = ctypes.c_void_p()
        self._rows = rows
        self._cols = cols
        self._matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        if self._matrix:
            gsl.gsl_matrix_free(self._matrix)

    @property
    def matrix(self):
        return self._matrix

    @property
    def rows(self):
        return self._rows

    @property
    def cols(self):
        return self._cols

    def to_numpy(self):
        data = np.zeros((self.rows, self.cols), dtype=np.float64)
        for i in range(self.rows):
            for j in range(self.cols):
                data[i, j] = gsl.gsl_matrix_get(self.matrix, i, j)
        return data

    @staticmethod
    def from_numpy(np_array):
        mat = GSLMatrix(np_array.shape[0], np_array.shape[1])
        for i in range(np_array.shape[0]):
            for j in range(np_array.shape[1]):
                gsl.gsl_matrix_set(mat.matrix, i, j, np_array[i, j])
        return mat

