import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = np.array(data, dtype=np.float64)
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0
        self._matrix = self._create_matrix()

    def _create_matrix(self):
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl_matrix_view = ctypes.c_void_p
        gsl_matrix_view.__class__ = ctypes.Structure

        c_matrix = ctypes.POINTER(ctypes.c_double)()
        c_matrix.contents = (ctypes.c_double * (self.rows * self.cols))(*self.data.flatten())

        matrix = libgsl.gsl_matrix_alloc(self.rows, self.cols)
        libgsl.gsl_matrix_set_from_pointer(matrix, c_matrix, self.rows, self.cols)
        return matrix

    def _get_index(self, index):
        return ctypes.c_int(index)

    def _get_row_col(self, index):
        row = self._get_index(index // self.cols)
        col = self._get_index(index % self.cols)
        return row, col

    def _get_minmax_indices(self):
        libgsl.gsl_matrix_minmax_index.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
        libgsl.gsl_matrix_minmax_index.restype = None

        min_index = ctypes.c_int(0)
        max_index = ctypes.c_int(0)

        libgsl.gsl_matrix_minmax_index(self._matrix, ctypes.byref(min_index), ctypes.byref(max_index))

        min_row, min_col = self._get_row_col(min_index.value)
        max_row, max_col = self._get_row_col(max_index.value)

        return (min_row.value, min_col.value, max_row.value, max_col.value)

    def find_minmax_indices(self):
        return self._get_minmax_indices()


def find_minmax_indices(matrix):
    mat = GSLMatrix(matrix)
    return mat.find_minmax_indices()

