    rows = len(lst)
    cols = len(lst[0]) if rows > 0 else 0
    matrix = GSLMatrix(None, rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix.data[i * cols + j] = lst[i][j]
    return matrix


