    try:
        rk2simp_alloc(-5)
    except ValueError as e:
        assert str(e) == "Dimension must be a positive integer.", "Incorrect error message for negative dimension."

    # Test case 3: Invalid dimension (zero)
    try:
        rk2simp_alloc(0)
    except ValueError as e:
        assert str(e) == "Dimension must be a positive integer.", "Incorrect error message for zero dimension."

