import numpy as np

class GSLVector:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()

    def set(self, data):
        for i in range(self.size):
            self.data[i] = data[i]

    def get(self):
        return np.array([self.data[i] for i in range(self.size)], dtype=np.float64)

class GSLSparseMatrix:
    def __init__(self, n):
        self.n = n
        self.data = (ctypes.c_double * 0)()
        self.indices = (ctypes.c_int * 0)()
        self.indptr = (ctypes.c_int * 0)()

    def set(self, data, indices, indptr):
        self.data = (ctypes.c_double * len(data))(*data)
        self.indices = (ctypes.c_int * len(indices))(*indices)
        self.indptr = (ctypes.c_int * len(indptr))(*indptr)

