gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def solve_gmres(A_data, A_indices, A_indptr, b, n, tol):
    b_vec = GSLVector(n)
    b_vec.set(b)

    A_mat = GSLSparseMatrix(n)
    A_mat.set(A_data, A_indices, A_indptr)

    x = GSLVector(n)
    status = gsl.gsl_linalg_solve_sparse_gmres(ctypes.c_void_p(id(A_mat)), ctypes.c_void_p(id(b_vec)), ctypes.c_void_p(id(x)), ctypes.c_double(tol))

    if status != 0:
        raise RuntimeError(f"GSL GMRES solver failed with status {status}")

    return x.get()

